//! A 3-dimensional SpecMap, whose second and third axes give the RA and Dec
//! of each point's source, matches C's (specmap.c `Transform` and
//! `FrameChange`): each case's dump loads with three axes and re-dumps as C
//! writes it, and its forward and inverse transformations, of points that
//! include bad values, equal C's bit for bit. A run of 3-dimensional SpecMaps
//! simplifies as C's does.
//!
//! `specmap_3d_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/specmap_3d_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "specmap_3d_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::mappings::{Mapping, SpecCvtType, SpecMap};
use ast_core::{AnyObject, from_native_string, to_native_string};

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

fn differs(got: &PointSet, want: &[[f64; 3]]) -> bool {
    (0..got.npoint()).any(|i| {
        got.point(i)
            .iter()
            .zip(&want[i])
            .any(|(g, w)| g.to_bits() != w.to_bits())
    })
}

#[test]
fn transformations_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, dump, input, forward, inverse) in cases::CASES {
        let obj = from_native_string(&text(dump)).unwrap();
        let got = to_native_string(&obj).unwrap();
        if got != text(dump) {
            failures.push(format!("{name} re-dump:\n{got}\nC gives:\n{}", text(dump)));
        }
        let map = obj.as_mapping().expect("a Mapping");
        assert_eq!(map.nin(), 3, "{name}");
        let pts = PointSet::from_rows(input.to_vec());
        for (dir, want) in [(true, forward), (false, inverse)] {
            let out = map.transform(&pts, dir).unwrap();
            if differs(&out, want) {
                failures.push(format!("{name} forward={dir}: {out:?}, C gives {want:?}"));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn a_built_specmap_dumps_as_c_does() {
    let mut map = SpecMap::with_nin(3).unwrap();
    map.add(SpecCvtType::LkF2Hl, &[0.1, 0.2]);
    let got = to_native_string(&AnyObject::SpecMap(map)).unwrap();
    let &(_, dump, ..) = cases::CASES.iter().find(|c| c.0 == "lsrk").expect("a case");
    assert_eq!(got, text(dump));
}

#[test]
fn only_one_or_three_axes() {
    for nin in [0, 2, 4] {
        assert!(SpecMap::with_nin(nin).is_err(), "{nin}");
    }
}

#[test]
fn simplification_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, input, want) in cases::SIMPLIFY_CASES {
        let obj = from_native_string(&text(input)).unwrap();
        let map = obj.as_mapping().expect("a Mapping");
        let simplified = <dyn Mapping>::simplify(map).unwrap();
        let out = AnyObject::from_mapping(simplified.as_ref()).expect("a known class");
        let got = to_native_string(&out).unwrap();
        if got != text(want) {
            failures.push(format!("{name}:\n{got}\nC gives:\n{}", text(want)));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
